(function(root,factory){if(typeof module==='object')module.exports=factory(require('./gastos_obras'),require('./persistencia_rdo'));else root.MartinsFinanceiro=factory(root.MartinsGastosObras,root.MartinsPersistenciaRdo);})(globalThis,(G,P)=>{'use strict';
const ACCOUNTS='cm_contas_financeiras_v1';
function accounts(rows){if(!Array.isArray(rows))throw Error('Cadastro de contas inválido; conteúdo preservado');const ids=new Set;for(const r of rows){if(!r||typeof r.id!=='string'||ids.has(r.id)||typeof r.nome!=='string'||!r.nome.trim()||!['Caixa','Banco','Outros'].includes(r.tipo))throw Error('Conta inválida; conteúdo preservado');ids.add(r.id);}return rows;}
function addAccount(rows,{nome,tipo,banco=''},actor,{id=P.newId(),now=new Date().toISOString()}={}){accounts(rows);nome=String(nome||'').trim();if(!nome||nome.length>120||!['Caixa','Banco','Outros'].includes(tipo)||!actor)throw Error('Informe nome (até 120 caracteres), tipo e responsável');banco=String(banco).trim();if(tipo==='Banco'&&(!banco||banco.length>120))throw Error('Informe qual é o banco (até 120 caracteres)');const norm=s=>s.normalize('NFKC').toLocaleLowerCase('pt-BR');if(rows.some(r=>r.id===id||norm(r.nome)===norm(nome)))throw Error('Conta já cadastrada');return [...structuredClone(rows),{id,nome,tipo,banco:tipo==='Banco'?banco:'',criadoPor:actor,criadoEm:now}];}
function create(input,works,rows,actor,options){accounts(rows);const account=rows.find(x=>x.id===input.contaId);if(!account)throw Error('Cadastre ou selecione uma conta financeira');if(input.status==='pendente'&&!input.vencimento)throw Error('Informe o vencimento da conta a pagar / receber');for(const x of input.rateios||[])if(!String(x.centroCusto||'').trim())throw Error('Informe o centro de custo após a obra');return G.create({...input,conta:account.nome,contaId:account.id},works,actor,options);}
function matchesPayee(value,query){const fold=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');return fold(value).includes(fold(query).trim());}
function due(rows,{tipo='despesa',today,from='',to='',situacao='todos',favorecido=''}={}){G.assertRows(rows);G.date(today);if(from)G.date(from);if(to)G.date(to);if(from&&to&&from>to)throw Error('Data inicial posterior à final');const result={rows:[],vencido:0,hoje:0,futuro:0,semData:0,total:0};for(const r of rows){if(r.tipo!==tipo||r.status!=='pendente'||favorecido&&!matchesPayee(r.favorecido,favorecido))continue;const state=!r.vencimento?'semData':r.vencimento<today?'vencido':r.vencimento===today?'hoje':'futuro';if(r.vencimento)G.date(r.vencimento);if(situacao!=='todos'&&state!==situacao)continue;if((from||to)&&!r.vencimento)continue;if(from&&r.vencimento<from||to&&r.vencimento>to)continue;result.rows.push({...structuredClone(r),situacaoVencimento:state});result[state]+=r.valorCentavos;result.total+=r.valorCentavos;}result.rows.sort((a,b)=>(a.vencimento||'9999').localeCompare(b.vencimento||'9999')||a.id.localeCompare(b.id));return result;}
function canReadWork(u){return Boolean(u&&u.status!=='Inativo'&&(G.canManage(u)||u.permissoes?.gestao===true||/Engenharia|Responsável Técnica/.test(u.perfil||'')));}
function workCsv(report,obra){const quote=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';const rows=[['Obra','Data','Empresa','Favorecido','Descrição','Centro de custo','Situação','Valor na obra (R$)'],...report.rows.map(r=>[obra,r.data.split('-').reverse().join('/'),r.empresa,r.favorecido,r.descricao,r.rateios.find(x=>x.obra===obra)?.centroCusto||'Sem centro de custo (anterior)',r.status,(r.valorExibido/100).toFixed(2).replace('.',',')])];return '\uFEFF'+rows.map(r=>r.map(quote).join(';')).join('\r\n');}
return {ACCOUNTS,accounts,addAccount,create,due,canReadWork,workCsv,matchesPayee};});
